do',1),('cmu3cvlkg0002vplt5x1sy3n3','cmtmci2fr000gvpvy2q8n05m0','photo','/fotos/larissa-e-fernando/beijo-arco.jpg','Primeiro beijo de casados',2),('cmu3cvlkg0003vplttw5oxwfe','cmtmci2fr000gvpvy2q8n05m0','photo','/fotos/larissa-e-fernando/abraco-mar.jpg','Só os dois na beira do mar',3),('cmu3cvlkg0004vpltbcpbok3q','cmtmci2fr000gvpvy2q8n05m0','photo','/fotos/larissa-e-fernando/caminhando-praia.jpg','Caminhando pela praia',4),('cmu3cvlkg0005vplt3qmq4cek','cmtmci2fr000gvpvy2q8n05m0','photo','/fotos/larissa-e-fernando/brinde-beijo.jpg','Brinde e beijo pra selar o dia',5);
